#include "cm_smcdure_cases.h"
static agc_t baseline;
static void row(uint16_t n,uint8_t phase){uint16_t w[2051];unsigned i;w[0]=n;w[1]=phase;w[2]=(uint16_t)machine.AllowInterrupt;for(i=0;i<2048u;++i)w[i+3u]=(uint16_t)((unsigned)*memory(i)&(i<2u?0177777u:077777u));if(fwrite(w,sizeof w,1,stdout)!=1)exit(2);if(n==0u)fprintf(stderr,"phase%u PC%o Q%o A%o L%o EB%o FB%o BB%o LOC%o EDOP%o CYR%o BANKSET%o POLISH%o ADDRWD%o PUSHLOC%o SR%o\n",phase,w[8],w[5],w[3],w[4],w[6],w[7],w[9],w[3+0164],w[3+023],w[3+020],w[3+0165],w[3+0117],w[3+0116],w[3+0166],w[3+021]);}
int main(int argc,char **argv){uint32_t n,limit=CM_SMCDURE_CASES;if(argc<2)return 2;if(argc>2)limit=(uint32_t)strtoul(argv[2],NULL,0);memset(&machine,0,sizeof machine);if(agc_load_binfile(&machine,argv[1]))return 2;baseline=machine;InhibitAlarms=1;for(n=0;n<limit;++n){apollo_overlay_state m;agc_word irq;unsigned i,cycles,pc=0,phase=0,prevpc=0,skip_noibank=0;cm_smcdure_input(&m,&irq,(uint16_t)n);machine=baseline;for(i=0;i<2048u;++i)*memory(i)=(int16_t)m.words[i];machine.AllowInterrupt=irq;for(cycles=0;cycles<20000u;++cycles){pc=get(RegZ);if(!machine.PendFlag&&!machine.ExtraDelay){if(pc==06037u&&cycles&&get(0164)==(02000u+(m.words[m.words[0120]+052u]&01777u))&&get(0117)==m.words[m.words[0120]+052u]){row((uint16_t)n,(uint8_t)phase++);break;}if(pc!=prevpc&&pc==06030u){row((uint16_t)n,(uint8_t)phase++);skip_noibank=1;}else if(pc!=prevpc&&pc==06032u){if(!skip_noibank)row((uint16_t)n,(uint8_t)phase++);skip_noibank=0;}prevpc=pc;}machine.ScalerCounter=0;if(agc_engine(&machine))return 2;}if(cycles==20000u){fprintf(stderr,"case%u timeoutPC%o Q%o phase%u\n",(unsigned)n,pc,get(2),phase);return 2;}}return 0;}
